package com.indice.erp.maintenance;

import com.indice.erp.access.module.RequiresModuleAccess;
import com.indice.erp.auth.AuthSessionUser;
import com.indice.erp.hr.assets.HrAssetMaintenanceContract;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import java.time.Instant;
import java.util.*;
import org.springframework.web.bind.annotation.*;
import static com.indice.erp.maintenance.MaintenanceDtos.*;
import static com.indice.erp.maintenance.MaintenancePolicy.*;

@RestController
@RequestMapping("/api/v1/maintenance")
@RequiresModuleAccess("maintenance")
public class MaintenanceController {
    private final MaintenanceAccess access;private final MaintenanceRepository db;private final MaintenanceService service;
    private final MaintenancePreventionService plans;private final MaintenanceEvidenceService evidence;
    private final MaintenanceCostService costs;private final HrAssetMaintenanceContract hr;private final MaintenanceTaskService tasks;private final MaintenanceTeamService team;private final MaintenanceCostSummaryService costSummary;
    public MaintenanceController(MaintenanceAccess access,MaintenanceRepository db,MaintenanceService service,MaintenancePreventionService plans,
        MaintenanceEvidenceService evidence,MaintenanceCostService costs,HrAssetMaintenanceContract hr,MaintenanceTaskService tasks,MaintenanceTeamService team,MaintenanceCostSummaryService costSummary){this.access=access;this.db=db;this.service=service;this.plans=plans;this.evidence=evidence;this.costs=costs;this.hr=hr;this.tasks=tasks;this.team=team;this.costSummary=costSummary;}
    private AuthSessionUser read(HttpSession s,String...tabs){return access.require(s,null,false,tabs);}
    private AuthSessionUser write(HttpSession s,String token,String tab){return access.require(s,token,true,tab);}
    static void page(String search,int page,int size){require(search.length()<=180&&page>=1&&page<=10000&&Set.of(10,25,50,100,200).contains(size),"maintenance_filters_invalid");}
    @GetMapping("/context") public Context context(HttpSession s){var a=read(s,"requests","orders","assets","preventive","indicators","configuration");return new Context(MaintenanceAccess.manager(a),MaintenanceAccess.administrator(a),a.userId(),access.assignment(a),access.ownerAccess(a,"inventory","inventory"),access.ownerAccess(a,"expenses","expenses"),access.ownerAccess(a,"human_resources","assets"),access.ownerAccess(a,"processes","calendar"),db.settings(a.companyId()));}
    @GetMapping("/settings") public Settings settings(HttpSession s){var a=read(s,"configuration");MaintenanceAccess.administrate(a);return db.settings(a.companyId());}
    @GetMapping("/settings/team") public Page<MaintenanceTeamService.Technician> team(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return team.list(read(s,"configuration"),search,page,pageSize);}
    @PutMapping("/settings/team/{id}") public MaintenanceTeamService.Technician team(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody MaintenanceTeamService.Update body){return team.update(write(s,token,"configuration"),id,body);}
    @PutMapping("/settings") public Settings settings(HttpSession s,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody Settings b){return service.settings(write(s,token,"configuration"),b);}
    @GetMapping("/assets") public Page<Asset> assets(HttpSession s,@RequestParam(defaultValue="name")String sort,@RequestParam(defaultValue="asc")String direction,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="false")boolean active,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return db.assets(read(s,"assets"),search,active,page,pageSize,sort,direction);}
    @GetMapping("/directories/assets") public Page<Asset> assetOptions(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return db.assets(read(s,"requests","orders","assets","preventive"),search,true,page,pageSize);}
    @GetMapping("/assets/{id}") public Asset asset(HttpSession s,@PathVariable long id){return db.asset(read(s,"assets"),id);}
    @PostMapping("/assets") public Asset asset(HttpSession s,@RequestHeader(value="X-CSRF-Token",required=false)String token,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody AssetInput b){return service.asset(write(s,token,"assets"),null,b,key);}
    @PutMapping("/assets/{id}") public Asset asset(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody AssetInput b){return service.asset(write(s,token,"assets"),id,b,null);}
    @PostMapping("/assets/{id}/restore") public Asset restore(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody VersionReason b){return service.restore(write(s,token,"assets"),id,b);}
    @GetMapping("/directories/hr-assets") public HrAssetMaintenanceContract.Page hrAssets(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return hr.search(read(s,"assets"),search,page,pageSize);}
    @GetMapping("/directories/members") public Page<Choice> members(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return db.members(read(s,"orders","configuration"),search,page,pageSize);}
    @GetMapping("/directories/units") public Page<Choice> units(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return access.organization(read(s,"assets"),false,null,search,page,pageSize);}
    @GetMapping("/directories/businesses") public Page<Choice> businesses(HttpSession s,@RequestParam(required=false)Long unitId,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return access.organization(read(s,"assets"),true,unitId,search,page,pageSize);}
    @GetMapping("/requests") public Page<RequestItem> requests(HttpSession s,@RequestParam(defaultValue="created")String sort,@RequestParam(defaultValue="desc")String direction,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="")String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);require(status.isEmpty()||Set.of("NEW","ACCEPTED","REJECTED").contains(status),"maintenance_status_invalid");return db.requests(read(s,"requests"),search,status,page,pageSize,sort,direction);}
    @GetMapping("/requests/{id}") public RequestDetail request(HttpSession s,@PathVariable long id){return db.requestDetail(read(s,"requests"),id);}
    @PostMapping("/requests") public RequestDetail request(HttpSession s,@RequestHeader(value="X-CSRF-Token",required=false)String token,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody RequestInput b){return service.report(write(s,token,"requests"),b,key);}
    @PostMapping("/requests/{id}/triage") public RequestDetail triage(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody Triage b){return service.triage(write(s,token,"requests"),id,b);}
    @GetMapping("/orders") public Page<Order> orders(HttpSession s,@RequestParam(defaultValue="due")String sort,@RequestParam(defaultValue="asc")String direction,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="")String status,@RequestParam(defaultValue="")String attention,@RequestParam(defaultValue="0")long assetId,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to){page(search,page,pageSize);require(status.isEmpty()||STATUSES.contains(status),"maintenance_status_invalid");require(Set.of("","open","overdue","critical","preventive").contains(attention)&&assetId>=0,"maintenance_filters_invalid");require((from==null)==(to==null),"maintenance_period_invalid");if(from!=null)require(from.isBefore(to)&&!to.isAfter(from.plusSeconds(366*86400L)),"maintenance_period_invalid");return db.orders(read(s,"orders"),search,status,attention,assetId,page,pageSize,from,to,sort,direction);}
    @GetMapping("/orders/{id}") public OrderDetail order(HttpSession s,@PathVariable long id){return db.detail(read(s,"orders"),id);}
    @PostMapping("/orders") public OrderDetail order(HttpSession s,@RequestHeader(value="X-CSRF-Token",required=false)String token,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody OrderInput b){return service.create(write(s,token,"orders"),b,key);}
    @PutMapping("/orders/{id}") public OrderDetail order(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody OrderInput b){return service.edit(write(s,token,"orders"),id,b);}
    @PutMapping("/orders/{id}/progress") public OrderDetail progress(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody Progress b){return service.progress(write(s,token,"orders"),id,b);}
    @PostMapping("/orders/{id}/status") public OrderDetail status(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody Transition b){return service.transition(write(s,token,"orders"),id,b);}
    @GetMapping("/plans") public Page<Plan> plans(HttpSession s,@RequestParam(defaultValue="next")String sort,@RequestParam(defaultValue="asc")String direction,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return plans.plans(read(s,"preventive"),search,page,pageSize,sort,direction);}
    @PostMapping("/plans") public Plan plan(HttpSession s,@RequestHeader(value="X-CSRF-Token",required=false)String token,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody PlanInput b){return plans.create(write(s,token,"preventive"),b,key);}
    @PostMapping("/plans/{id}/status") public Plan plan(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody Toggle b){return plans.toggle(write(s,token,"preventive"),id,b);}
    @GetMapping("/metrics/costs") public MaintenanceCostSummaryService.Summary costSummary(HttpSession s,@RequestParam Instant from,@RequestParam Instant to){return costSummary.summary(read(s,"indicators"),from,to);}
    @GetMapping("/metrics") public Metrics metrics(HttpSession s,@RequestParam Instant from,@RequestParam Instant to){return plans.metrics(read(s,"indicators"),from,to);}
    @PostMapping("/evidence/{type}/{id}/upload") public UploadTicket upload(HttpSession s,@PathVariable String type,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody UploadInput b){return evidence.presign(write(s,token,MaintenanceEvidenceService.tab(type)),type,id,b);}
    @PostMapping("/evidence/{type}/{id}/register") public List<Attachment> register(HttpSession s,@PathVariable String type,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody RegisteredUpload b){return evidence.register(write(s,token,MaintenanceEvidenceService.tab(type)),type,id,b.id());}
    @GetMapping("/evidence/{type}/{id}") public List<Attachment> evidence(HttpSession s,@PathVariable String type,@PathVariable long id){return evidence.list(read(s,MaintenanceEvidenceService.tab(type)),type,id);}
    @GetMapping("/evidence/{type}/{id}/{attachment}") public Download download(HttpSession s,@PathVariable String type,@PathVariable long id,@PathVariable long attachment){return evidence.download(read(s,MaintenanceEvidenceService.tab(type)),type,id,attachment);}
    @GetMapping("/orders/{id}/costs") public Costs costs(HttpSession s,@PathVariable long id){return costs.costs(read(s,"orders"),id);}
    @GetMapping("/directories/stock") public Object stock(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(required=false)String cursor){page(search,1,25);return costs.balances(read(s,"orders"),search,cursor);}
    @GetMapping("/directories/expenses") public Page<ExpenseLink> expenses(HttpSession s,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="25")int pageSize){page(search,page,pageSize);return costs.expenseOptions(read(s,"orders"),search,page,pageSize);}
    @PostMapping("/orders/{id}/labor") public OrderDetail labor(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody LaborInput b){return costs.labor(write(s,token,"orders"),id,b,key);}
    @PostMapping("/orders/{id}/labor/{entry}/reverse") public OrderDetail reverseLabor(HttpSession s,@PathVariable long id,@PathVariable long entry,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody VersionReason b){return costs.reverseLabor(write(s,token,"orders"),id,entry,b);}
    @PostMapping("/orders/{id}/parts") public OrderDetail parts(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid @RequestBody PartInput b){return costs.part(write(s,token,"orders"),id,b,key);}
    @PostMapping("/orders/{id}/parts/{entry}/reverse") public OrderDetail reversePart(HttpSession s,@PathVariable long id,@PathVariable long entry,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody VersionReason b){return costs.reversePart(write(s,token,"orders"),id,entry,b);}
    @PostMapping("/orders/{id}/expenses") public OrderDetail expense(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody ExpenseInput b){return costs.linkExpense(write(s,token,"orders"),id,b);}
    @PostMapping("/orders/{id}/task") public OrderDetail task(HttpSession s,@PathVariable long id,@RequestHeader(value="X-CSRF-Token",required=false)String token,@Valid @RequestBody VersionReason b){return tasks.create(write(s,token,"orders"),id,b.expectedVersion());}
}
